<?php $pageTitle='Browse fresh fish';require 'includes/header.php'; $q=trim($_GET['q']??'');$category=(int)($_GET['category']??0);$min=$_GET['min']??'';$max=$_GET['max']??'';$sort=$_GET['sort']??'new';
$where=["p.is_available=1","sp.approval_status='approved'"];$args=[];if($q!==''){$where[]='(p.name LIKE ? OR p.description LIKE ?)';$args[]="%$q%";$args[]="%$q%";}if($category){$where[]='p.category_id=?';$args[]=$category;}if($min!==''&&is_numeric($min)){$where[]='p.price>=?';$args[]=$min;}if($max!==''&&is_numeric($max)){$where[]='p.price<=?';$args[]=$max;}$orders=['low'=>'p.price ASC','high'=>'p.price DESC','new'=>'p.created_at DESC'];
$sql='SELECT p.*,sp.shop_name,c.name category FROM products p JOIN seller_profiles sp ON p.seller_id=sp.id JOIN categories c ON p.category_id=c.id WHERE '.implode(' AND ',$where).' ORDER BY '.($orders[$sort] ?? $orders['new']);$s=db()->prepare($sql);$s->execute($args);$products=$s->fetchAll();$cats=db()->query('SELECT * FROM categories WHERE is_active=1 ORDER BY name')->fetchAll();?>
<div class="page-title"><p class="eyebrow">MARKETPLACE</p><h1>Fresh fish & seafood</h1><p>From trusted local sellers, priced transparently.</p></div><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search fish"><select name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$category===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><input type="number" name="min" min="0" value="<?=e($min)?>" placeholder="Min ₹"><input type="number" name="max" min="0" value="<?=e($max)?>" placeholder="Max ₹"><select name="sort"><option value="new">Newest</option><option value="low" <?=$sort==='low'?'selected':''?>>Price: low first</option><option value="high" <?=$sort==='high'?'selected':''?>>Price: high first</option></select><button>Apply</button></form>
<p class="result-count"><?=count($products)?> fresh listings found</p><section class="product-grid"><?php foreach($products as $p):require 'includes/product-card.php';endforeach;?></section><?php if(!$products):?><div class="empty">🐟<h2>No catch matches your filters.</h2><a href="products.php">Clear filters</a></div><?php endif; require 'includes/footer.php'; ?>
